 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                         if y in (r0,r1) or x in (c0,c1)}
            if set(comp) == perimeter:
                frames.append((color, r0, r1, c0, c1, perimeter))
    frame_cells = set().union(*(f[5] for f in frames)) if frames else set()
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r,c) not in frame_cells)
    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1, perimeter in frames:
        for r,c in perimeter:
            out[r][c] = color
        target = ((r1-r0-1)*(c1-c0-1)+1)//2
        candidates = [k for k,v in counts.items() if v == target]
        if candidates:
            fill = candidates[0]
            for r in range(r0+1, r1):
                for c in range(c0+1, c1):
                    if (r-r0-1 + c-c0-1) % 2 == 0:
                        out[r][c] = fill
    return out

